// ═══ CARA KERJA DRAG PHYSICS ═══

// 1. RUBBER-BAND RESISTANCE
// Saat card di-drag, resistance naik seiring jarak:
const rubber = 1 / (1 + dist * 0.001)
// dist=0 → rubber=1 (bebas), dist=500 → rubber=0.67 (melambat)

// 2. SPRING-BACK ANIMATION
// Setelah dilepas, card kembali ke posisi awal:
velocity = (velocity - offset * stiffness) * damping
// stiffness=0.08 → kembali pelan
// damping=0.78 → overshoot sedikit (efek spring)

// 3. 3D TILT FROM VELOCITY
// Tilt mengikuti kecepatan drag:
tiltX = clamp(-velocityX * 1.2, -18, 18) // derajat
// Kiri → tilt kiri, kanan → tilt kanan

// 4. WOBBLE ON RELEASE
// Setelah spring selesai, card bergetar sekali:
animation: idCardWobble 0.6s cubic-bezier(0.34, 1.56, 0.64, 1)
// cubic-bezier overshoot = efek getar natural

// ═══ LANYARD SVG PATHS ═══

// Tali menggunakan Cubic Bezier (C) dengan 4 kontrol titik:
// M startX startY                    — mulai dari hook
// C ctrl1X ctrl1Y ctrl2X ctrl2Y endX endY  — curve ke buckle

// Hook posisi: (130, 12) — fixed, tidak bergerak
// Buckle posisi: (130 + offsetX, 186 + offsetY) — ikut card

// Control points bergeser proporsional dengan offset:
const c1x = hookX - 38 + dx * 0.08  // titik kontrol 1
const c1y = hookY + dy * 0.32        // 32% dari total jarak
const c2x = buckleX - 8 + dx * 0.15  // titik kontrol 2  
const c2y = hookY + dy * 0.72        // 72% dari total jarak

// Hasil: S-curve natural yang fleksibel mengikuti card

/* ═══ KEY CSS TECHNIQUES ═══ */

/* 1. SVG overflow: visible — tali render di luar SVG bounds */
.id-card-lanyard {
  position: absolute;
  top: 0;
  width: 260px;
  height: 420px;
  overflow: visible; /* CRITICAL */
  pointer-events: none;
  z-index: 10;
}

/* 2. Gradient fade — tali transparan di dekat buckle */
linearGradient {
  stop[92%] { stop-opacity: 1 }   /* opaque sampai 92% */
  stop[100%] { stop-opacity: 0 }  /* fade di 100% */
}
/* objectBoundingBox → fade selalu di ujung bawah path */

/* 3. 3D Perspective tilt */
.id-card {
  transform-style: preserve-3d;
  transform: perspective(800px) rotateY(Xdeg) rotateX(Ydeg);
}

/* 4. Wobble animation — overshoot cubic-bezier */
@keyframes idCardWobble {
  0%  { transform: perspective(800px) rotateY(0) rotateX(0); }
  20% { transform: perspective(800px) rotateY(4deg) rotateX(-2deg); }
  40% { transform: perspective(800px) rotateY(-3deg) rotateX(1.5deg); }
  60% { transform: perspective(800px) rotateY(2deg) rotateX(-1deg); }
  80% { transform: perspective(800px) rotateY(-1deg) rotateX(0.5deg); }
  100% { transform: perspective(800px) rotateY(0) rotateX(0); }
}

/* 5. Glow border — mask-composite exclude */
.id-card-glow {
  background: linear-gradient(135deg, #8B5CF6, #3B82F6, #8B5CF6);
  mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  mask-composite: exclude; /* hanya border yang glowing */
  padding: 2px;
}

/* 6. Unique SVG IDs — hindari konflik saat multiple instance */
linearGradient :id="`strapFill-${uid}"
